import { test, expect } from '@playwright/test';

test.describe('Dynamic Loading - Async Content Reveal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  test('should hide finish element initially', async ({ page }) => {
    const finishElement = page.locator('#finish');
    await expect(finishElement).toBeHidden();
  });

  test('should show loading indicator when start button is clicked', async ({ page }) => {
    const startButton = page.getByRole('button', { name: /start/i });
    const loadingIndicator = page.locator('#loading');

    await startButton.click();
    await expect(loadingIndicator).toBeVisible();
  });

  test('should reveal finish element with correct text after loading completes', async ({ page }) => {
    const startButton = page.getByRole('button', { name: /start/i });
    const loadingIndicator = page.locator('#loading');
    const finishElement = page.locator('#finish');

    await startButton.click();
    await expect(loadingIndicator).toBeVisible();

    await expect(loadingIndicator).toBeHidden({ timeout: 10000 });
    await expect(finishElement).toBeVisible();
    await expect(finishElement).toContainText('Hello World!');
  });

  test('should complete full workflow from start to finish', async ({ page }) => {
    const startButton = page.getByRole('button', { name: /start/i });
    const loadingIndicator = page.locator('#loading');
    const finishElement = page.locator('#finish');

    await expect(finishElement).toBeHidden();

    await startButton.click();
    await expect(loadingIndicator).toBeVisible();

    await expect(loadingIndicator).toBeHidden({ timeout: 10000 });
    await expect(finishElement).toBeVisible();
    await expect(finishElement).toHaveText('Hello World!');
  });
});
